"""Temporary browser control surface for an operator-managed agent."""

from fastapi.responses import HTMLResponse


PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Afterglow relay</title><style>
:root{color-scheme:dark;--bg:#10171c;--panel:#18242a;--ink:#e7f1ec;--muted:#98aaa4;--line:#385049;--signal:#e6b35a;--safe:#83d5b2;--danger:#e27770}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -20%,#274943,transparent 40%),var(--bg);color:var(--ink);font:15px ui-monospace,SFMono-Regular,Menlo,monospace}main{max-width:1040px;margin:auto;padding:44px 22px}header{display:flex;justify-content:space-between;gap:16px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:22px}h1{font:600 clamp(28px,5vw,52px)/.92 Georgia,serif;letter-spacing:-.04em;margin:0}small,.muted{color:var(--muted)}.state{color:var(--signal)}section{margin-top:28px;background:color-mix(in srgb,var(--panel) 92%,black);border:1px solid var(--line);padding:20px}h2{margin:0 0 16px;font-size:12px;letter-spacing:.13em;text-transform:uppercase;color:var(--safe)}form,.row{display:grid;grid-template-columns:1.2fr 1fr auto;gap:10px;align-items:center}input,button{font:inherit;border:1px solid var(--line);border-radius:0;padding:11px;background:#0d1417;color:var(--ink)}button{cursor:pointer;background:var(--signal);color:#17201d;border-color:var(--signal);font-weight:bold}button.danger{background:transparent;border-color:var(--danger);color:var(--danger)}#clients{display:grid;gap:8px;margin-top:14px}.client{display:grid;grid-template-columns:1fr auto auto;gap:10px;padding:12px 0;border-top:1px solid var(--line)}a{color:var(--safe)}#notice{min-height:1.2em;color:var(--muted)}@media(max-width:620px){header,form,.row,.client{display:block}.client>*{margin:7px 0;width:100%}input,button{width:100%;margin:4px 0}}
</style><main><header><div><small>AFTERGLOW / TEMPORARY OPERATOR CONSOLE</small><h1>Relay custody</h1></div><div id="status" class="state">connecting</div></header><section><h2>Bearer session</h2><form onsubmit="saveToken(event)"><input id="token" type="password" placeholder="API bearer token" autocomplete="current-password"><button>Connect</button><span id="notice"></span></form></section><section><h2>Issue client</h2><form onsubmit="createClient(event)"><input id="name" placeholder="Client name" required maxlength="64"><input id="dns" placeholder="DNS (default 1.1.1.1)"><input id="routes" placeholder="Routes (0.0.0.0/0)"><input id="mtu" type="number" min="1280" max="1500" value="1420" aria-label="MTU"><input id="keepalive" type="number" min="0" max="65535" value="25" aria-label="Persistent keepalive"><button>Create profile</button></form></section><section><h2>Managed peers</h2><div id="clients" class="muted">Connect with a bearer token to load clients.</div></section><dialog id="edit-dialog"><form id="edit-form" onsubmit="saveEdit(event)"><h2>Edit peer</h2><input id="edit-name" required><input id="edit-routes" required><input id="edit-dns"><input id="edit-mtu" type="number" min="1280" max="1500" required><input id="edit-keepalive" type="number" min="0" max="65535" required><label><input id="edit-enabled" type="checkbox"> Enabled</label><button type="button" onclick="cancelEdit()">Cancel</button><button type="submit">Save changes</button></form></dialog></main><script>
let token='',polling=false,clientRows=new Map(),editingId=null;const notice=t=>document.querySelector('#notice').textContent=t;async function api(path,opt={}){let r=await fetch(path,{...opt,headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json',...(opt.headers||{})}});if(!r.ok){let j=await r.json().catch(()=>null);throw Error(j?.error?.message||r.statusText)}return r}function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function fmt(n){return n==null?'—':n<1024?n+' B':(n/1024).toFixed(1)+' KiB'}async function refresh(){if(polling)return;polling=true;try{let [s,c,t]=await Promise.all([api('/api/v1/status'),api('/api/v1/clients'),api('/api/v1/traffic')]);s=await s.json();c=(await c.json()).clients;clientRows=new Map(c.map(x=>[x.id,x]));let traffic=new Map((await t.json()).peers.map(x=>[x.public_key,x]));document.querySelector('#status').textContent=`${s.state} · ${s.enabled_peer_count}/${s.peer_count} enabled`;document.querySelector('#clients').innerHTML=c.length?c.map(x=>`<div class="client"><div><b>${esc(x.name)}</b><br><small>${x.address} · ${x.connected?'connected':'idle'} · ${fmt(traffic.get(x.public_key)?.transfer_rx_bytes)}↓ ${fmt(traffic.get(x.public_key)?.transfer_tx_bytes)}↑ · ${fmt(traffic.get(x.public_key)?.rx_bytes_per_second)}↓/s ${fmt(traffic.get(x.public_key)?.tx_bytes_per_second)}↑/s</small></div><button onclick="downloadProfile('${x.id}')">Download profile</button><button onclick="editClient('${x.id}')">Edit</button><button class="danger" onclick="removeClient('${x.id}')">Delete</button></div>`).join(''):'No clients issued yet.';notice('')}catch(e){document.querySelector('#status').textContent='authorization required';notice(e.message)}finally{polling=false}}function saveToken(e){e.preventDefault();token=document.querySelector('#token').value.trim();refresh()}async function createClient(e){e.preventDefault();try{let body={name:document.querySelector('#name').value,mtu:Number(document.querySelector('#mtu').value),persistent_keepalive:Number(document.querySelector('#keepalive').value)};let dns=document.querySelector('#dns').value.trim(),routes=document.querySelector('#routes').value.trim();if(dns)body.dns=dns.split(',').map(x=>x.trim());if(routes)body.allowed_ips=routes.split(',').map(x=>x.trim());let r=await api('/api/v1/clients',{method:'POST',body:JSON.stringify(body)});let c=await r.json();notice(`Created ${c.name}. Download its profile from the list.`);e.target.reset();refresh()}catch(e){notice(e.message)}}function editClient(id){let x=clientRows.get(id);if(!x)return;editingId=id;for(let [k,v] of Object.entries({name:x.name,routes:x.allowed_ips.join(','),dns:x.dns.join(','),mtu:x.mtu,keepalive:x.persistent_keepalive})){document.querySelector('#edit-'+k).value=v}document.querySelector('#edit-enabled').checked=x.enabled;document.querySelector('#edit-dialog').showModal()}function cancelEdit(){let d=document.querySelector('#edit-dialog');if(d.open)d.close()}async function saveEdit(e){e.preventDefault();if(!editingId)return;let routes=document.querySelector('#edit-routes').value.trim(),dns=document.querySelector('#edit-dns').value.trim();try{await api('/api/v1/clients/'+editingId,{method:'PATCH',body:JSON.stringify({name:document.querySelector('#edit-name').value.trim(),allowed_ips:routes.split(',').map(v=>v.trim()).filter(Boolean),dns:dns.split(',').map(v=>v.trim()).filter(Boolean),mtu:Number(document.querySelector('#edit-mtu').value),persistent_keepalive:Number(document.querySelector('#edit-keepalive').value),enabled:document.querySelector('#edit-enabled').checked})});cancelEdit();refresh()}catch(e){notice(e.message)}}document.querySelector('#edit-dialog').addEventListener('close',()=>{editingId=null});async function downloadProfile(id){try{let r=await api('/api/v1/clients/'+id+'/config');let u=URL.createObjectURL(await r.blob());let a=document.createElement('a');a.href=u;a.download='client-'+id+'.conf';a.click();setTimeout(()=>URL.revokeObjectURL(u),0)}catch(e){notice(e.message)}}async function removeClient(id){if(!confirm('Delete this client and revoke its profile?'))return;try{await api('/api/v1/clients/'+id,{method:'DELETE'});refresh()}catch(e){notice(e.message)}}setInterval(()=>{if(token)refresh()},5000);</script></html>'''


def temporary_console() -> HTMLResponse:
    return HTMLResponse(PAGE, headers={"Cache-Control": "no-store"})
